<section class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2">My learning dashboard</h1><p class="text-muted">Continue your enrolled courses.</p></div><a href="/courses" class="btn btn-outline-primary">Browse courses</a></div><div class="row g-4"><?php if (!$enrollments): ?><div class="col-12"><div class="alert alert-info">You are not enrolled in any courses yet.</div></div><?php endif; ?><?php foreach ($enrollments as $enrollment): ?><div class="col-md-6"><div class="card shadow-sm"><div class="card-body"><h2 class="h5"><?= e($enrollment['title']) ?></h2><div class="progress mb-2"><div class="progress-bar" style="width:<?= e((string) $enrollment['progress']) ?>%"></div></div><div class="small text-muted"><?= e((string) $enrollment['progress']) ?>% complete · <?= e($enrollment['status']) ?></div><a class="btn btn-sm btn-primary mt-3" href="/learn?course=<?= urlencode($enrollment['slug']) ?>">Continue learning</a></div></div></div><?php endforeach; ?></div></section>